// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makePolygon } from "@remotion/shapes";



export type CacaoMoleculeProps = Record<string, any>;

const CacaoMoleculeAnimation: React.FC<CacaoMoleculeProps> = ({
  backgroundColor = "#1a0d0a",
  transparentBackground = false,
  durationInSeconds = 8,
  podColor = "#4a2114",
  podInsideColor = "#f4d8b8",
  particleColor = "#ffd700",
  glowColor = "#ffa500",
  particleCount = 80,
  moleculeCount = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Calculate canvas center, shifting down slightly to allow vertical upwards drift
  const cx = width / 2;
  const cy = height / 2 + 100;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Configurations
  const totalFrames = fps * durationInSeconds;
  const splitStart = 30;
  const splitEnd = 120;
  const dissolveStart = totalFrames - 60;
  const dissolveEnd = totalFrames;

  // Pod Splitting Physics
  const splitProgress = interpolate(frame, [splitStart, splitEnd], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  // Custom smoothstep easing for an organic, slow split
  const easeSplit = splitProgress * splitProgress * (3 - 2 * splitProgress); 
  const splitDistance = easeSplit * 65;
  const splitAngle = easeSplit * 22;

  // Pre-compute geometric paths for the dopamine/serotonin stylized molecules
  const hexPath = React.useMemo(() => makePolygon({ points: 6, radius: 25 }).path, []);
  const pentPath = React.useMemo(() => makePolygon({ points: 5, radius: 18 }).path, []);

  // Generate Particle Array mapping deterministic trajectories
  const particles = Array.from({ length: particleCount }).map((_, i) => {
    const rDelay = random(`p_delay_${i}`);
    const rStart = random(`p_xStart_${i}`);
    const rWander = random(`p_xWander_${i}`);
    const rSize = random(`p_size_${i}`);

    const startFrame = splitStart + 10 + rDelay * 90;
    const endFrame = startFrame + 90 + rStart * 60;

    const progress = interpolate(frame, [startFrame, endFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const opacity = interpolate(progress, [0, 0.1, 0.7, 1], [0, 1, 0.8, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

    const y = interpolate(progress, [0, 1], [0, -height * 0.7 - rDelay * 200]);
    const xBase = interpolate(rStart, [0, 1], [-60, 60]);
    const xEnd = xBase + interpolate(rWander, [0, 1], [-300, 300]);

    // Apply sine wave perturbation for organic drifting
    const x = interpolate(progress, [0, 1], [xBase, xEnd]) + Math.sin(frame * 0.05 + rDelay * 20) * 50;
    const size = interpolate(rSize, [0, 1], [2, 6]);

    return { x, y, size, opacity };
  });

  // Generate Molecular Structures drifting upwards
  const molecules = Array.from({ length: moleculeCount }).map((_, i) => {
    const rDelay = random(`m_delay_${i}`);
    const rStart = random(`m_xStart_${i}`);
    const rRot = random(`m_rot_${i}`);

    const startFrame = splitStart + 60 + rDelay * 60;
    const endFrame = startFrame + 120 + rDelay * 40;

    const progress = interpolate(frame, [startFrame, endFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const opacity = interpolate(progress, [0, 0.2, 0.6, 1], [0, 1, 0.9, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

    const y = interpolate(progress, [0, 1], [0, -height * 0.6 - rDelay * 100]);
    const x = interpolate(rStart, [0, 1], [-300, 300]) + Math.sin(frame * 0.03 + rDelay * 5) * 80;

    const rot = interpolate(progress, [0, 1], [rRot * 180, rRot * 180 + 90]);
    const scale = interpolate(progress, [0, 0.2, 1], [0, 1, 1.2]);

    return { x, y, rot, scale, opacity };
  });

  // Global opacity fade for the transition into soft warm light
  const sceneFade = interpolate(frame, [dissolveStart, dissolveEnd], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const softLightFade = interpolate(frame, [dissolveStart, dissolveEnd], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        <defs>
          {/* Bloom Filter applied to glowing elements */}
          <filter id="glowBloom" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="12" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          {/* Ambient Background Radial */}
          <radialGradient id="bgGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor={glowColor} stopOpacity={0.4} />
            <stop offset="100%" stopColor={backgroundColor} stopOpacity={0} />
          </radialGradient>
        </defs>

        {/* Dynamic expanding background glow */}
        <circle
          cx={cx}
          cy={cy - height * 0.3}
          r={interpolate(frame, [0, totalFrames], [200, 1200])}
          fill="url(#bgGlow)"
          opacity={interpolate(frame, [0, splitStart, totalFrames], [0, 0.5, 1]) * sceneFade}
          style={{ transition: "none" }}
        />

        <g style={{ opacity: sceneFade, transition: "none" }}>
          {/* Main Cacao Pod Setup */}
          <g transform={`translate(${cx}, ${cy})`}>
            
            {/* Inner Pulp Exposed by Hinging */}
            <path
              d="M 0,-180 C -70,-180 -110,-90 -110,0 C -110,90 -70,180 0,180 C 70,180 110,90 110,0 C 110,-90 70,-180 0,-180 Z"
              fill={podInsideColor}
            />

            {/* Left Pod Shell hinged at bottom */}
            <g transform={`translate(${-splitDistance}, 0) rotate(${-splitAngle}, 0, 180)`}>
              <path d="M 0,-200 C -100,-200 -140,-100 -140,0 C -140,100 -100,200 0,200 Z" fill={podColor} />
              {/* Organic Ridges */}
              <path d="M -30,-190 C -70,-100 -70,100 -30,190" stroke="rgba(0,0,0,0.3)" strokeWidth={6} fill="none" />
              <path d="M -70,-170 C -110,-80 -110,80 -70,170" stroke="rgba(0,0,0,0.3)" strokeWidth={6} fill="none" />
            </g>

            {/* Right Pod Shell hinged at bottom */}
            <g transform={`translate(${splitDistance}, 0) rotate(${splitAngle}, 0, 180)`}>
              <path d="M 0,-200 C 100,-200 140,-100 140,0 C 140,100 100,200 0,200 Z" fill={podColor} />
              {/* Organic Ridges */}
              <path d="M 30,-190 C 70,-100 70,100 30,190" stroke="rgba(0,0,0,0.3)" strokeWidth={6} fill="none" />
              <path d="M 70,-170 C 110,-80 110,80 70,170" stroke="rgba(0,0,0,0.3)" strokeWidth={6} fill="none" />
            </g>

            {/* Particle Emitter starting slightly above the bottom hinge inside pulp */}
            <g transform="translate(0, -20)" filter="url(#glowBloom)">
              {particles.map((p, i) => (
                <circle 
                  key={`p-${i}`} 
                  cx={p.x} 
                  cy={p.y} 
                  r={p.size} 
                  fill={particleColor} 
                  opacity={p.opacity} 
                  style={{ transition: "none" }}
                />
              ))}
            </g>

            {/* Molecular Structure Emitter */}
            <g transform="translate(0, -50)" filter="url(#glowBloom)">
              {molecules.map((m, i) => (
                <g 
                  key={`m-${i}`} 
                  transform={`translate(${m.x}, ${m.y}) rotate(${m.rot}) scale(${m.scale})`} 
                  opacity={m.opacity}
                  style={{ transition: "none" }}
                >
                  <g stroke={particleColor} strokeWidth={3} fill="transparent" strokeLinecap="round" strokeLinejoin="round">
                    {/* Hexagon Base */}
                    <path d={hexPath} />
                    {/* Pentagon Attachment */}
                    <g transform="translate(42, 18) rotate(15)">
                      <path d={pentPath} />
                    </g>
                    {/* Connecting Molecular Bonds */}
                    <line x1={20} y1={8} x2={26} y2={12} />
                    <line x1={-24} y1={0} x2={-35} y2={-10} />
                    <line x1={-12} y1={-20} x2={-18} y2={-35} />
                  </g>
                </g>
              ))}
            </g>
          </g>
        </g>

        {/* Global Dissolve Layers Into Warm Light */}
        <rect
          x={0}
          y={0}
          width={width}
          height={height}
          fill={glowColor}
          opacity={softLightFade * 0.8}
          style={{ mixBlendMode: "screen", transition: "none" }}
        />
        {/* Final push towards warm white light */}
        <rect 
          x={0} 
          y={0} 
          width={width} 
          height={height} 
          fill="#fff3e0" 
          opacity={softLightFade * softLightFade} 
          style={{ transition: "none" }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default CacaoMoleculeAnimation;